        final LinkedBlockingQueue<Question> questions = new LinkedBlockingQueue<>();
        final LinkedBlockingQueue<BackendSession.End> ends = new LinkedBlockingQueue<>();
        public void statusChanged(BackendSession.Status status) {
            states.add(status);
