    WorkspaceQueries queries();

    /** 变更事件流（订阅句柄 {@code close()} 即退订）。 */
    PortEvents events();

    /** 确认往返（卡片断开/顶替 = 取消交付，方案 §14 决策 11）。 */
    Confirmer confirmer();
}

